export const DATA_39: ReadingTest[] = [
  { id: "rd-046", num: 46, title: "Đề 046", timeMin: 60, parts: [
    { title: "The Growth and Impact of InBook", paragraphs: ["Reading for pleasure has long been considered one of the most rewarding habits a person can develop. In recent years, however, many people have struggled to find time to read, particularly those living busy urban lives filled with work, family, and digital distractions. It was this challenge that inspired two university friends, Linh and Marco, to launch InBook — a community-based reading platform that helps everyday people rediscover the joy of books. What began as a small online group has since grown into a thriving network with members in over thirty countries.", "InBook works on a simple but effective model. Members sign up for free on the platform's website or mobile app and are matched with a reading group based on their interests, availability, and preferred language. Groups typically consist of five to eight people who agree to read one book per month and meet virtually every two weeks to discuss their progress. The discussions are informal and friendly, guided by a set of open-ended questions provided by InBook's team of volunteers. No prior reading experience or academic background is required to join.", "One of the most celebrated features of InBook is its book exchange programme. Rather than purchasing new books, members are encouraged to send their used books to other members around the world. Each book travels with a small card inside, recording the names of all the people who have read it. Some books have passed through dozens of hands across multiple continents, collecting handwritten notes and personal reflections from each reader. Members describe receiving these well-travelled books as one of the most meaningful parts of the experience.", "The platform has also had a measurable impact on its members' wellbeing. An internal survey conducted last year found that seventy-three percent of regular InBook users reported feeling less lonely since joining, and sixty-one percent said their reading habit had improved their ability to manage stress. Several members noted that the reading groups gave them a reliable sense of routine and social connection — two things that many people, especially those living alone, often find difficult to maintain. Psychologists who have reviewed InBook's approach have described it as a low-cost yet highly effective form of community building.", "InBook has also taken steps to make reading more accessible to people who face barriers to traditional reading. The platform offers audiobook options for members with visual impairments or reading difficulties, and it actively recruits bilingual volunteers to lead groups for non-native speakers. In addition, InBook has partnered with several public libraries and community centres to provide free membership to people in lower-income households. These efforts have been recognised with two social innovation awards in the past three years.", "Despite its success, InBook continues to operate as a non-profit organisation. Linh and Marco have consistently rejected offers from commercial publishers and technology companies who wish to invest in or acquire the platform. \"Our goal was never to build a business,\" Linh explained in a recent interview. \"We wanted to create a space where people could connect through stories. The moment we start treating readers as customers, we lose what makes InBook special.\" This commitment to its founding values has earned InBook a loyal and passionate community of members who regularly advocate for its mission on social media and in their local communities."], questions: [{ q: "What is the passage mainly about?", options: ["The challenges that urban people face when trying to read regularly", "Why non-profit organisations are more trustworthy than commercial companies", "The history of reading clubs around the world", "How InBook was created, how it operates, and the difference it has made"], answer: 3 }, { q: "According to the passage, how are InBook reading groups typically structured?", options: ["Large groups of twenty or more people who meet in person every week", "Open groups with no size limit that allow members to join at any time", "Small groups of five to eight people who read a book monthly and meet online every two weeks", "Pairs of members who are matched based on their reading speed"], answer: 2 }, { q: "What happens to books that are shared through InBook's exchange programme?", options: ["They are scanned and made available as digital copies on the platform", "They are donated to school libraries in developing countries", "They travel with a card recording each reader's name and personal reflections", "They are professionally restored before being sent to new members"], answer: 2 }, { q: "According to the internal survey mentioned in the passage, what percentage of regular InBook users said their reading habit helped them deal with stress?", options: ["Sixty-one percent", "Fifty percent", "Eighty percent", "Seventy-three percent"], answer: 0 }, { q: "Which of the following is mentioned as one of InBook's efforts to make reading more accessible?", options: ["Providing audiobook options and recruiting bilingual volunteers", "Offering free printed books to all new members", "Creating a separate platform for children under the age of twelve", "Building physical reading centres in major cities"], answer: 0 }, { q: "The word \"them\" in paragraph 4 refers to _______.", options: ["the reading groups themselves", "Linh and Marco, the founders of InBook", "psychologists who reviewed InBook's approach", "regular InBook users, especially those living alone"], answer: 3 }, { q: "According to the passage, which of the following is NOT mentioned as a way InBook supports members with barriers to traditional reading?", options: ["Recruiting bilingual volunteers to lead groups for non-native speakers", "Providing audiobook options for members with visual impairments", "Offering free membership to people in lower-income households", "Translating all books into at least five languages before distribution"], answer: 3 }, { q: "The word \"advocate\" in paragraph 6 is closest in meaning to _______.", options: ["criticise", "promote and support", "join", "investigate"], answer: 1 }, { q: "Based on information in the passage, why do members find receiving \"well-travelled\" books particularly meaningful?", options: ["Because members can sell the books at a higher price after reading them", "Because the books are rare collector's editions that are difficult to buy in shops", "Because the books arrive with a record of previous readers and their handwritten thoughts", "Because the books are always in perfect condition when they arrive"], answer: 2 }, { q: "What is the author's overall attitude toward InBook and its founders?", options: ["Neutral, presenting both the strengths and weaknesses of the platform equally", "Admiring, highlighting the platform's positive impact and the founders' dedication to their values", "Doubtful, questioning whether InBook's success can continue without financial backing", "Critical, suggesting that InBook should accept commercial investment to grow faster"], answer: 1 }] },
    { title: "The Rise and Fall of Ancient Civilizations", paragraphs: ["Throughout human history, great civilizations have risen to remarkable heights, only to eventually weaken and disappear. Scholars across multiple disciplines — including archaeology, environmental science, and political history — have long sought to understand the forces that drive both the flourishing and the decline of ancient societies. While no single explanation accounts for every case, researchers have identified a number of recurring patterns that appear to play a significant role in shaping a civilization's fate.", "One of the most well-documented factors in the collapse of ancient civilizations is environmental degradation. The Mesopotamian civilizations of the Tigris-Euphrates river valley, for example, built highly sophisticated irrigation systems that allowed them to transform dry land into productive farmland. However, centuries of intensive irrigation led to the gradual accumulation of salt in the soil — a process known as salinisation. Over time, this rendered large areas of land infertile, severely reducing food production and destabilising the agricultural foundations upon which these societies depended. Similar patterns of resource depletion have been observed in the decline of the ancient Maya in Central America, where deforestation for agricultural expansion contributed to soil erosion and prolonged droughts.", "Political instability is another factor that historians frequently associate with civilizational decline. Internal conflicts over power, resources, and succession often weakened central authority, leaving states increasingly vulnerable to both internal unrest and external threats. The Western Roman Empire, for instance, experienced several decades of near-constant civil war, economic crisis, and political corruption before its final collapse in 476 CE. Historians debate whether the empire fell primarily because of internal decay or external pressure from migrating peoples, but most agree that the two forces reinforced each other, creating a spiral of decline that proved impossible to reverse.", "Trade disruption also played a significant role in the downfall of several ancient powers. Many civilizations relied heavily on long-distance trade networks to obtain resources that were not available locally, such as metals, timber, and luxury goods. When these networks collapsed — due to conflict, natural disasters, or the rise of competing powers — the economic consequences could be severe. The Bronze Age Collapse of around 1200 BCE is a striking example: within a few decades, several interconnected Mediterranean civilizations, including the Mycenaean Greeks and the Hittites, simultaneously disappeared. Scholars believe that the disruption of trade routes, combined with natural disasters and population movements, created a cascading effect that no single society could withstand.", "It is important to note, however, that not all civilizations simply \"fell\" in a dramatic and sudden manner. Many underwent gradual transformations rather than outright collapses. The ancient Egyptian civilisation, for example, persisted for over three thousand years, absorbing waves of foreign conquest and cultural influence while maintaining a recognisable core identity. Similarly, the Byzantine Empire — the eastern continuation of Rome — survived for nearly a thousand years after the fall of the Western Roman Empire, adapting its political, religious, and military structures in response to changing circumstances.", "What distinguishes civilizations that endure from those that perish? Resilience appears to be a key factor. Societies that demonstrated flexibility — the ability to adapt their agricultural practices, political systems, and trade relationships in response to crises — were more likely to survive long-term disruptions. The degree of social cohesion also mattered: communities with strong shared values, effective leadership, and inclusive institutions tended to recover more successfully from setbacks than those fragmented by inequality and division.", "The study of ancient civilizations carries important lessons for the modern world. Today's global society faces its own set of interlinked challenges — climate change, political polarisation, economic inequality, and the fragility of complex supply chains — that bear a striking resemblance to the pressures that contributed to past collapses. While modern technology and international cooperation offer tools that were unavailable to ancient peoples, historians caution that these advantages are not a guarantee of stability. The past reminds us that even the most powerful and sophisticated societies are not immune to decline."], questions: [{ q: "What is the main purpose of the passage?", options: ["To compare the achievements of Mesopotamian and Roman civilizations", "To argue that environmental destruction is the single most important cause of civilizational collapse", "To examine the recurring factors behind the rise and fall of ancient civilizations and draw lessons for today", "To demonstrate that all ancient civilizations followed the same pattern of rise and decline"], answer: 2 }, { q: "According to the passage, what agricultural problem contributed to the weakening of Mesopotamian civilizations?", options: ["The gradual build-up of salt in the soil caused by intensive irrigation", "Overuse of pesticides that poisoned the river water", "A sudden drought that dried up the Tigris and Euphrates rivers", "Prolonged flooding that destroyed irrigation infrastructure"], answer: 0 }, { q: "According to the passage, what combination of problems weakened the Western Roman Empire before its fall?", options: ["Trade collapse, volcanic eruptions, and invasion by Eastern empires", "Famine, religious conflict, and the loss of key trade routes", "Overpopulation, foreign debt, and agricultural failure", "Internal civil war, economic crisis, and political corruption"], answer: 3 }, { q: "Which of the following best describes the Bronze Age Collapse according to the passage?", options: ["A single catastrophic volcanic eruption that destroyed several Mediterranean cities", "The simultaneous disappearance of several interconnected civilizations, likely due to multiple combined pressures", "A slow economic decline caused by the rise of iron-based trade replacing bronze", "A military conquest in which one dominant empire absorbed all surrounding territories"], answer: 1 }, { q: "According to the passage, which of the following is NOT given as an example of a civilization that transformed gradually rather than collapsing suddenly?", options: ["Ancient Egypt, which lasted over three thousand years", "The Hittite Empire, which adapted its military structures over many centuries", "Rome, whose eastern continuation survived long after the western part collapsed", "The Byzantine Empire, which continued for nearly a thousand years after Rome's fall"], answer: 1 }, { q: "According to the passage, which quality is identified as a key factor in helping civilizations endure?", options: ["The ability to adapt practices and maintain social cohesion in times of crisis", "Access to large reserves of natural resources such as metals and timber", "Military dominance over neighbouring territories", "Strict hierarchical governance with a powerful centralised ruler"], answer: 0 }, { q: "The word \"accounts\" in paragraph 1 is closest in meaning to _______.", options: ["describes briefly", "records", "fully explains", "calculates"], answer: 2 }, { q: "The word \"these\" in paragraph 7 (\"these advantages are not a guarantee of stability\") refers to _______.", options: ["the lessons learned from studying ancient civilizational collapses", "modern technology and international cooperation", "the trade networks that ancient civilizations depended upon", "the challenges facing modern global society such as climate change and inequality"], answer: 1 }, { q: "The word \"cascading\" in paragraph 4 is closest in meaning to _______.", options: ["spreading in a chain reaction where each problem triggers further problems", "slow and gradual over many decades", "violent and direct", "limited to a single geographic region"], answer: 0 }, { q: "What can be inferred from the final paragraph about the author's view of modern civilization?", options: ["The author suggests that modern societies are in a worse position than ancient civilizations because of climate change", "The author implies that despite modern advantages, today's societies are not automatically protected from decline", "The author concludes that international cooperation has already solved the major threats facing humanity", "The author believes that modern technology makes today's societies completely immune to collapse"], answer: 1 }] },
    { title: "The Intense Competition in the AI Industry", paragraphs: ["Artificial intelligence has shifted from a narrow academic discipline into one of the most fiercely contested arenas in modern industry. Within the span of roughly a decade, what was once the domain of university research laboratories has become a battleground for some of the world's largest and best-funded corporations. [1] The race to develop more capable AI systems now involves not only technology giants such as Google, Microsoft, and Amazon, but also a rapidly expanding ecosystem of well-capitalised start-ups, national governments, and sovereign wealth funds. Few technological competitions in history have attracted such concentrated investment in such a compressed timeframe.", "At the heart of this competition lies the pursuit of what researchers call \"general-purpose\" AI — systems capable of performing a wide variety of cognitive tasks across different domains, rather than excelling at a single narrow function. Early AI systems were designed to do one thing well: play chess, recognise faces, or translate text. The ambition driving today's competition is considerably broader. Companies are pouring resources into building models that can reason, generate creative content, write functional code, and assist with complex decision-making processes. [2] The commercial potential of such systems is considered enormous, which explains why investment in the sector reached an estimated 91 billion US dollars globally in a single recent year.", "The competition has reshaped the labour market for AI talent in dramatic ways. A small number of researchers and engineers with specialised expertise in areas such as deep learning, reinforcement learning, and large-scale model training have become extraordinarily sought after. Their salaries at leading AI companies frequently exceed those of executives in many traditional industries, and it is not uncommon for top researchers to receive compensation packages valued in the tens of millions of dollars. This concentration of talent at a handful of elite institutions has raised concerns among academics and policymakers who worry that the most capable AI researchers are being drawn away from universities and public research programmes, potentially slowing independent scientific progress.", "National governments have increasingly come to view AI leadership as a matter of strategic importance comparable to nuclear capability or space dominance during the Cold War. The United States and China, in particular, have made AI development a central pillar of their broader economic and national security strategies. Washington has introduced export controls on advanced semiconductors — the physical hardware required to train and run large AI models — in an effort to limit China's access to cutting-edge computing resources. Beijing, in response, has accelerated domestic investment in chip manufacturing and AI research, aiming to achieve self-sufficiency in critical technologies by the mid-2030s. [3] The involvement of governments at this level has transformed what might otherwise have been a purely commercial rivalry into a geopolitical contest with far-reaching consequences.", "The concentration of power within the AI industry has also drawn the attention of competition regulators in Europe, the United States, and elsewhere. Critics argue that a small number of companies control the vast majority of the computing infrastructure, proprietary datasets, and specialised talent required to develop frontier AI systems, creating barriers to entry that prevent meaningful competition from smaller players. Several major technology mergers and partnerships involving AI companies have been scrutinised by antitrust authorities, though regulatory outcomes have so far been mixed. Defenders of the current structure counter that the enormous capital requirements of frontier AI research make large-scale consolidation not merely inevitable but necessary for continued progress.", "Perhaps the most consequential dimension of the AI competition concerns safety and the long-term trajectory of the technology. As companies race to release increasingly capable models ahead of their rivals, critics within the research community have warned that competitive pressure may lead organisations to cut corners on safety testing and alignment research — the technical work aimed at ensuring that AI systems behave in accordance with human values and intentions. [4] Several prominent AI researchers have publicly called for internationally coordinated governance frameworks that would establish minimum safety standards across the industry, arguing that the risks of an ungoverned AI race outweigh the benefits of accelerated development. Whether governments and industry leaders will respond to these calls with meaningful action remains, at the time of writing, an open question."], questions: [{ q: "What is the passage primarily concerned with?", options: ["Why China and the United States are the two dominant players in global AI development", "The technical differences between narrow AI and general-purpose AI systems", "The multidimensional nature of competition in the AI industry, including its economic, geopolitical, and safety dimensions", "The negative impact of the AI industry on university research programmes worldwide"], answer: 2 }, { q: "According to the passage, approximately how much was invested globally in the AI sector in a single recent year?", options: ["191 billion US dollars", "9.1 billion US dollars", "91 billion US dollars", "910 million US dollars"], answer: 2 }, { q: "According to the passage, why did the United States introduce export controls on advanced semiconductors?", options: ["To encourage domestic chip production by eliminating competition from Chinese imports", "To restrict China's ability to access the computing hardware needed to develop advanced AI", "To protect American semiconductor manufacturers from foreign price competition", "To slow the pace of AI development globally in response to safety concerns"], answer: 1 }, { q: "According to the passage, what concern have academics and policymakers raised about the concentration of AI talent at large companies?", options: ["That the movement of top researchers away from universities may slow independent scientific progress", "That high salaries make AI research inaccessible to talented people from lower-income backgrounds", "That leading AI companies are training researchers to pursue commercial goals rather than scientific ones", "That executives in traditional industries are being replaced by AI specialists at an unsustainable rate"], answer: 0 }, { q: "According to the passage, what argument do defenders of large AI companies make in response to concerns about market concentration?", options: ["That consolidation is unavoidable and arguably necessary given the enormous cost of frontier AI research", "That access to proprietary datasets is the only real barrier to entry for new AI companies", "That regulatory oversight of AI mergers should be left entirely to the private sector", "That smaller companies lack the creativity to produce meaningful AI innovations"], answer: 0 }, { q: "According to the passage, which of the following is NOT mentioned as a capability that modern AI companies aim to develop in their systems?", options: ["The ability to write functional computer code", "The ability to reason across different domains", "The ability to control physical robotic systems in manufacturing", "The ability to generate creative content"], answer: 2 }, { q: "The word \"alignment\" in paragraph 6 is closest in meaning to _______.", options: ["the commercial strategy of matching AI products to specific market segments", "the coordination of research timelines between competing AI laboratories", "the physical arrangement of components within an AI system", "the process of ensuring AI behaviour corresponds to human values and intentions"], answer: 3 }, { q: "The word \"scrutinised\" in paragraph 5 is closest in meaning to _______.", options: ["rejected outright by regulatory bodies", "approved quickly with minimal review", "publicly announced to increase transparency", "examined very carefully and in detail"], answer: 3 }, { q: "The word \"Their\" in paragraph 3 refers to _______.", options: ["executives in traditional industries", "academics and policymakers who have raised concerns about talent concentration", "leading AI companies that dominate the industry", "a small number of researchers and engineers with specialised AI expertise"], answer: 3 }, { q: "Which of the following square brackets [1] , [2] , [3] , or [4] best indicates where the following sentence could be added? \"Some observers liken this dynamic to an arms race, in which no participant can afford to slow down for fear of being overtaken.\"", options: ["[1]", "[2]", "[3]", "[4]"], answer: 2 }] },
    { title: "The Environmental Toll of the Digital Age: E-waste and Energy Consumption", paragraphs: ["The digital revolution has transformed virtually every aspect of modern life, generating unprecedented gains in productivity, communication, and access to information. Yet the material and energetic foundations upon which this transformation rests are rarely examined with the same enthusiasm that greets each successive wave of technological innovation. [1] Beneath the seamless interface of the smartphone and the cloud lies a vast, largely hidden infrastructure of resource extraction, manufacturing, energy consumption, and waste — an infrastructure whose environmental costs are, by most credible assessments, both substantial and accelerating.", "Electronic waste, commonly abbreviated as e-waste, now constitutes the world's fastest-growing solid waste stream. The Global E-waste Monitor, an authoritative annual report produced by a consortium of United Nations agencies, estimated that approximately 62 million metric tonnes of e-waste were generated worldwide in a single recent year — a figure that represents a 82 percent increase over the volume recorded two decades earlier. The proliferation of consumer electronics — smartphones, laptops, tablets, wearable devices, and the hardware underpinning so-called smart homes — has compressed product replacement cycles to the point where devices are frequently discarded not because they have ceased to function, but because manufacturers have rendered them obsolete through software discontinuation or deliberate incompatibility with newer accessories.", "The consequences of improper e-waste disposal are severe and well-documented. Many electronic devices contain a mixture of valuable materials — including gold, silver, palladium, and rare earth elements — alongside highly toxic substances such as lead, mercury, cadmium, and brominated flame retardants. When discarded devices are processed by informal recyclers in low-regulation environments, as is common in parts of West Africa and South and Southeast Asia, these toxic compounds are released into the surrounding soil, water, and air. Studies conducted in communities adjacent to informal e-waste processing sites have recorded elevated concentrations of neurotoxic heavy metals in the blood of children, as well as statistically significant increases in rates of respiratory illness and developmental disorders. [2] The burden of this contamination falls disproportionately on populations that have contributed least to the consumption patterns driving e-waste generation.", "The energy demands of the digital economy represent a parallel and equally complex environmental challenge. Data centres — the physical facilities that store, process, and transmit the information underpinning cloud computing, streaming services, social media platforms, and increasingly AI applications — collectively consume an estimated one to two percent of global electricity. While this figure may appear modest in isolation, it must be contextualised against a backdrop of rapid and compounding growth: global data traffic has roughly doubled every two years for the past decade, and the training of a single large AI language model has been estimated to generate carbon emissions comparable to the lifetime output of several conventional passenger vehicles. The energy intensity of AI workloads, in particular, is projected to increase substantially as models grow in scale and complexity.", "Proponents of the digital sector frequently invoke the concept of dematerialisation — the idea that digital services replace more resource-intensive physical alternatives, yielding a net environmental benefit. A video call, the argument runs, produces far fewer emissions than an equivalent long-haul flight; digital documents eliminate the need for paper; e-commerce consolidates delivery routes and reduces the aggregate number of individual shopping trips. These arguments are not without merit, but critics contend that they consistently underestimate the rebound effect: the tendency for efficiency gains to stimulate additional consumption rather than reduce overall resource use. The proliferation of high-definition video streaming, for instance, has generated data traffic volumes that far exceed any savings attributable to reduced physical media production.", "Regulatory frameworks addressing the environmental impact of digital technology have developed unevenly across jurisdictions. The European Union has led the field with its Ecodesign Regulation and the proposed Right to Repair legislation, which seek to extend product lifespans, mandate the availability of spare parts, and require manufacturers to provide software updates for a minimum number of years. Comparable initiatives in other major markets remain nascent or absent altogether. [3] Industry self-regulation, meanwhile, has produced some genuine commitments — several large technology companies have pledged to operate on one hundred percent renewable energy and achieve net-zero carbon emissions by mid-century — but sceptics note that such pledges frequently rely on carbon offsetting mechanisms whose effectiveness and permanence are disputed.", "Addressing the environmental toll of the digital age will require interventions at multiple levels simultaneously. [4] Technological solutions — more energy-efficient chips, improved battery chemistries, advances in materials recovery — are necessary but insufficient in isolation; they cannot compensate for growth trajectories that continue to outpace efficiency improvements. Policy measures, shifts in consumer behaviour, and, arguably most fundamentally, a rethinking of the innovation imperative itself — the assumption that faster, newer, and more capable technology is self-evidently desirable — may all prove indispensable. Whether the digital sector can reconcile its appetite for expansion with the planetary boundaries within which all human activity must ultimately operate remains one of the defining questions of the coming decades."], questions: [{ q: "What is the central argument of the passage?", options: ["The environmental costs of the digital age — including e-waste and energy consumption — are serious and growing, and addressing them requires action at multiple levels", "The energy efficiency gains achieved by the technology industry have outpaced the growth in digital consumption, resulting in an overall net environmental benefit", "Digital technology is inherently incompatible with environmental sustainability and should be significantly scaled back", "Regulatory frameworks, particularly in the European Union, have largely succeeded in containing the environmental damage caused by the digital sector"], answer: 0 }, { q: "According to the passage, by approximately how much did global e-waste volumes increase over the two decades preceding the most recent estimate?", options: ["They increased by 62 percent", "They roughly doubled, representing an increase of around 50 percent", "They grew by 82 percent", "They tripled, increasing by approximately 200 percent"], answer: 2 }, { q: "According to the passage, what health effects have been documented in communities near informal e-waste processing sites?", options: ["Widespread contamination of drinking water with industrial solvents from dismantled batteries", "Increased rates of cancer linked to long-term exposure to electromagnetic radiation", "A rise in cardiovascular disease among adult workers employed directly in the recycling process", "Elevated levels of neurotoxic heavy metals in children's blood and higher rates of respiratory illness and developmental disorders"], answer: 3 }, { q: "According to the passage, what does training a single large AI language model produce in terms of carbon emissions?", options: ["An amount of carbon that can be fully offset through standard renewable energy certificates", "Emissions equivalent to the annual energy consumption of a medium-sized data centre", "Emissions roughly equivalent to the lifetime output of several conventional passenger vehicles", "A negligible amount, comparable to a short domestic flight"], answer: 2 }, { q: "According to the passage, which of the following is NOT mentioned as part of the European Union's regulatory approach to digital technology and the environment?", options: ["Requirements for manufacturers to support products with software updates for a minimum period", "Legislation aimed at giving consumers the right to repair their devices", "The Ecodesign Regulation, which seeks to extend the lifespan of electronic products", "A mandatory carbon tax applied to data centres based on their annual energy consumption"], answer: 3 }, { q: "The word \"this\" in paragraph 4 (\"While this figure may appear modest in isolation\") refers to _______.", options: ["the carbon emissions generated by training a single large AI language model", "the projected increase in energy intensity of AI workloads as models grow in scale", "data centres' collective consumption of an estimated one to two percent of global electricity", "the rapid doubling of global data traffic every two years"], answer: 2 }, { q: "The word \"rendered\" in paragraph 2 is closest in meaning to _______.", options: ["gradually transformed through natural wear", "displayed visually", "deliberately made", "officially classified by a regulatory body"], answer: 2 }, { q: "The word \"nascent\" in paragraph 6 is closest in meaning to _______.", options: ["permanently discontinued due to lack of political support", "highly developed and comprehensively enforced", "only just beginning to develop and not yet fully formed", "controversial and actively opposed by industry groups"], answer: 2 }, { q: "What can be inferred about the author's attitude toward technology industry pledges on renewable energy and net-zero emissions?", options: ["The author acknowledges the pledges as genuine commitments while implying that their actual impact is uncertain and potentially overstated", "The author believes that voluntary pledges are more effective than legally binding regulation in changing corporate behaviour", "The author regards them as wholly fraudulent and driven exclusively by public relations concerns", "The author considers them sufficient on their own to resolve the environmental challenges described in the passage"], answer: 0 }, { q: "Which of the following square brackets [1] , [2] , [3] , or [4] best indicates where the following sentence could be added? \"Such a disparity raises pointed questions about the equity of global environmental governance.\"", options: ["[1]", "[2]", "[3]", "[4]"], answer: 1 }] },
  ] },
  { id: "rd-069", num: 69, title: "Đề 069", timeMin: 60, parts: [
    { title: "Home Entertainment Devices in the Modern Age", paragraphs: ["Over the past two decades, home entertainment has changed dramatically. Not long ago, families gathered around a single television set in the living room to watch programs together. Today, however, the situation is very different. Most households in developed countries now own several entertainment devices, including smart TVs, laptops, tablets, gaming consoles, and smartphones. Each member of the family can enjoy their own content at the same time, in different rooms, and on different screens.", "One of the most significant changes has been the rise of streaming services. Platforms such as Netflix, Disney+, and YouTube have made it possible for people to watch movies, series, and other video content on demand — meaning they can choose what to watch and when to watch it. This is very different from traditional television, where viewers had to follow a fixed schedule. The convenience of streaming has led many households to cancel their cable TV subscriptions entirely, a trend known as \"cord-cutting.\" According to a recent survey, nearly 40% of households in the United States have stopped paying for cable television in favor of internet-based alternatives.", "Gaming consoles have also become much more than simple toys for children. Modern consoles like the PlayStation and Xbox can connect to the internet, allowing users to play with or against other people around the world. They also support video streaming, music playback, and even video calls. As a result, these devices are now considered full home entertainment systems rather than gaming-only equipment. For many young adults, a gaming console has replaced the need for a separate media player, smart TV app system, or music speaker.", "Smart speakers are another category of home entertainment device that has grown rapidly in popularity. Devices such as Amazon Echo and Google Home respond to voice commands and can play music, answer general knowledge questions, control smart home appliances, and even tell jokes. Many users appreciate how hands-free these devices are — you simply speak, and the device responds. However, some people have raised concerns about privacy, arguing that these speakers are always listening and may collect personal data without the owner fully realizing it.", "Tablets and e-readers have changed the way people read books and magazines. Rather than visiting a library or bookstore, readers can download thousands of titles in seconds. E-readers like the Amazon Kindle are designed specifically for reading, with screens that are easy on the eyes even in bright sunlight. Tablets, on the other hand, offer a wider range of functions, from reading to video calling to drawing and gaming. For many people, especially those who travel frequently, carrying a single tablet is far more practical than bringing several books or magazines.", "Despite all these advances, not everyone is happy with the growing number of screens in the home. Some parents worry that children are spending too much time in front of devices and not enough time playing outdoors or talking with family members. Health experts have also warned that too much screen time, especially before bedtime, can disrupt sleep patterns and cause eye strain. As a result, many families are setting screen time limits and creating \"device-free\" zones in the home, such as the dining room and the bedroom.", "In summary, home entertainment devices have brought many benefits, including greater choice, convenience, and connectivity. At the same time, they have introduced new challenges related to health, privacy, and family interaction. Finding the right balance between enjoying modern technology and maintaining a healthy lifestyle remains an important goal for many households today."], questions: [{ q: "What is the main idea of the passage?", options: ["Streaming services are replacing traditional cable television around the world.", "Children are spending too much time using entertainment devices at home.", "Modern home entertainment devices offer many benefits but also present new challenges.", "Home entertainment devices have made it easier for families to spend time together."], answer: 2 }, { q: "According to the passage, what does the term \"cord-cutting\" refer to?", options: ["Reducing the number of devices connected to the internet at home.", "Replacing old televisions with newer smart TV models.", "Households choosing to stop paying for cable TV and switching to online services.", "Parents setting time limits on how long children can use entertainment devices."], answer: 2 }, { q: "According to the passage, which of the following is a function of modern gaming consoles BESIDES playing games?", options: ["Replacing smart speakers and answering voice commands.", "Playing music, streaming video, and making video calls.", "Downloading e-books and displaying digital magazines.", "Printing documents and controlling home security cameras."], answer: 1 }, { q: "According to the passage, what do smart speakers like Amazon Echo allow users to do?", options: ["Connect to gaming consoles and improve the sound quality.", "Download movies directly to an external hard drive.", "Control appliances and get answers to questions using their voice.", "Monitor their children's screen usage throughout the day."], answer: 2 }, { q: "The word \"convenience\" in paragraph 2 is closest in meaning to _______.", options: ["ease of use", "entertainment value", "expense", "popularity"], answer: 0 }, { q: "According to the passage, how is an e-reader like the Kindle different from a tablet?", options: ["The Kindle is heavier and harder to carry than a tablet.", "The Kindle can display video content, while tablets are only for reading.", "The Kindle is designed specifically for reading, while tablets offer many more functions.", "The Kindle can connect to the internet, while tablets cannot."], answer: 2 }, { q: "The word \"They\" in paragraph 3 refers to _______.", options: ["Users who play games with people around the world.", "Modern gaming consoles such as PlayStation and Xbox.", "Smart TV apps and separate media players.", "Young adults who have replaced their music speakers."], answer: 1 }, { q: "According to the passage, which of the following is NOT mentioned as something smart speakers can do?", options: ["Control smart home appliances.", "Play music on request.", "Answer general knowledge questions.", "Stream live television programs."], answer: 3 }, { q: "The word \"disrupt\" in paragraph 6 is closest in meaning to _______.", options: ["record", "extend", "interfere with", "improve"], answer: 2 }, { q: "What is the author's overall attitude toward home entertainment devices?", options: ["Strongly against, claiming that devices cause more harm than good.", "Balanced, recognizing both the advantages and the problems they bring.", "Uncertain, as the author does not express a clear opinion on the topic.", "Strongly in favor, arguing that all families should use as many devices as possible."], answer: 1 }] },
    { title: "Motorbike Touring in Vietnam: A Unique Cultural Experience", paragraphs: ["Vietnam has long been one of Southeast Asia's most captivating travel destinations, drawing visitors with its dramatic landscapes, rich history, and vibrant street culture. In recent years, however, a new form of tourism has gained enormous popularity among both domestic and international travelers: motorbike touring. Rather than observing the country through the window of a bus or the porthole of a tour boat, motorbike travelers immerse themselves directly in the sights, sounds, and rhythms of Vietnamese life. This hands-on approach to travel has transformed the way the world experiences Vietnam.", "The appeal of motorbike touring lies partly in the extraordinary diversity of Vietnam's terrain. From the terraced rice fields of Sapa in the northern highlands to the sun-soaked beaches of Mui Ne in the south, the country offers a remarkable range of scenery within a relatively compact geography. The famous Ho Chi Minh Road, which stretches nearly 1,800 kilometers along the country's mountainous spine, is considered one of the most scenic motorbike routes in Asia. Riders who complete the full journey from Hanoi to Ho Chi Minh City encounter dense jungle, winding mountain passes, and quiet coastal fishing villages — experiences that simply cannot be replicated by any other means of transport.", "Beyond the scenery, motorbike touring allows travelers to engage with local communities in ways that organized group tours rarely permit. When a rider stops at a roadside stall for a bowl of pho or pulls over to ask for directions in a small village, genuine human connections often follow. Many touring veterans describe these spontaneous encounters as the most memorable parts of their journeys. Local residents, particularly in rural areas, often welcome foreign visitors with great warmth and curiosity, turning a brief roadside stop into an extended conversation or even an invitation to share a meal.", "The motorbike itself has deep cultural significance in Vietnam. With over 45 million registered motorcycles in the country, the motorbike is far more than a vehicle — it is a symbol of everyday life, commerce, and mobility. Vendors use motorbikes to carry astonishing loads of goods to market. Parents use them to take children to school. Entire families of four or five are sometimes seen balanced on a single bike moving through urban traffic. For foreign tourists, riding a motorbike is therefore not only a way to see the country but also a way to participate, however briefly, in one of its most defining cultural practices.", "Nevertheless, motorbike touring in Vietnam is not without its difficulties. The country's road conditions vary enormously, from smooth highways in the lowlands to unpaved mountain tracks that become dangerously muddy during the rainy season. Traffic in major cities like Hanoi and Ho Chi Minh City can be overwhelming for inexperienced riders, with motorbikes, cars, trucks, and pedestrians all competing for space in what can appear to be choreographed chaos. Accidents involving tourists are not uncommon, which is why travel safety organizations consistently advise riders to wear proper helmets, carry international driving licenses, and avoid riding at night.", "Despite these challenges, the market for motorbike tourism has grown steadily. Several local companies now offer guided tours, rental services, and comprehensive route-planning assistance tailored specifically to foreign travelers. Online communities and travel blogs have also played a significant role in spreading knowledge and enthusiasm for the activity. Travelers share detailed route guides, advice on mechanical repairs, and recommendations for budget accommodation in remote areas — forming a global network of motorbike touring enthusiasts who keep the culture alive and accessible.", "In this way, motorbike touring has become more than a travel trend. It has evolved into a meaningful framework through which visitors explore not only Vietnam's spectacular geography but also the everyday realities of its people. For those willing to accept a degree of unpredictability and physical challenge, the open road offers rewards that no guided bus tour can match."], questions: [{ q: "What is the main purpose of the passage?", options: ["To compare motorbike touring with other forms of transportation in Southeast Asia.", "To describe how motorbike touring offers travelers both scenic and cultural experiences in Vietnam.", "To warn tourists about the dangers of riding motorbikes in Vietnam.", "To argue that Vietnam's road conditions need improvement for international tourists."], answer: 1 }, { q: "According to the passage, which of the following is true about the Ho Chi Minh Road?", options: ["It connects Sapa in the north directly to the beaches of Mui Ne.", "It is considered the safest motorbike route in Asia for foreign travelers.", "It is a coastal highway running along the eastern edge of Vietnam.", "It stretches approximately 1,800 kilometers through the country's mountainous interior."], answer: 3 }, { q: "According to the passage, how do Vietnamese people typically use motorbikes in their daily lives?", options: ["Mainly for recreational activities such as weekend touring.", "Primarily for long-distance travel between provinces and cities.", "For everyday tasks including transporting goods and taking children to school.", "Mostly for commercial delivery services in urban areas."], answer: 2 }, { q: "The word \"immerse\" in paragraph 1 is closest in meaning to _______.", options: ["observe from a distance", "involve themselves deeply in", "document carefully", "move quickly through"], answer: 1 }, { q: "According to the passage, which of the following is a challenge that motorbike tourists may face in Vietnam?", options: ["Strict government regulations that limit tourist access to rural routes.", "A lack of motorbike rental services outside major cities.", "An absence of online resources for planning motorbike routes.", "Unpredictable road conditions that can become hazardous in wet weather."], answer: 3 }, { q: "According to the passage, what role have online communities played in motorbike tourism?", options: ["They have helped share route information, repair tips, and accommodation advice among enthusiasts.", "They have lobbied governments to improve road infrastructure for tourists.", "They have organized large-scale international motorbike events across Vietnam.", "They have provided official safety certifications to rental companies."], answer: 0 }, { q: "The word \"it\" in paragraph 4 refers to _______.", options: ["the motorbike.", "the act of carrying goods to market.", "commerce and mobility in general.", "everyday life in Vietnam."], answer: 0 }, { q: "The word \"spontaneous\" in paragraph 3 is closest in meaning to _______.", options: ["repeated and predictable", "happening naturally without prior arrangement", "limited to specific cultural events", "carefully planned in advance"], answer: 1 }, { q: "According to the passage, which of the following is NOT mentioned as safety advice for motorbike tourists in Vietnam?", options: ["Avoiding riding after dark.", "Completing a certified motorbike safety course before departure.", "Carrying an international driving license.", "Wearing a proper helmet at all times."], answer: 1 }, { q: "What can be inferred about the author's attitude toward motorbike touring in Vietnam?", options: ["The author feels that guided group tours are ultimately more rewarding than independent motorbike travel.", "The author is neutral and presents no personal view on the activity.", "The author views motorbike touring positively, seeing it as a uniquely rewarding way to experience the country despite its risks.", "The author believes it is too dangerous for most tourists and should be discouraged."], answer: 2 }] },
    { title: "The Rise of Autonomous Vehicles: Navigating the Future", paragraphs: ["For most of the twentieth century, the automobile represented personal freedom — a machine that gave its driver total control over speed, direction, and destination. That relationship between human and vehicle is now undergoing its most profound transformation since the invention of the internal combustion engine. Autonomous vehicles, commonly referred to as self-driving cars, are no longer a distant fantasy confined to science fiction. Several technology companies and traditional automakers have already deployed fleets of driverless vehicles on public roads, and the global race to perfect this technology is accelerating with each passing year.", "At the heart of autonomous vehicle technology lies a complex integration of sensors, artificial intelligence, and real-time data processing. Most self-driving systems rely on a combination of cameras, radar, and LiDAR — a laser-based sensing technology that creates highly detailed three-dimensional maps of the surrounding environment. These are processed simultaneously by onboard computers that can evaluate thousands of variables per second, enabling the vehicle to detect obstacles, read traffic signals, predict the movements of pedestrians and other drivers, and make split-second navigational decisions without human input. Engineers describe the resulting system as far more attentive than any human driver, since it does not suffer from fatigue, distraction, or emotional impairment.", "The potential safety benefits of autonomous vehicles are frequently cited as the primary justification for their development. Road traffic accidents claim approximately 1.35 million lives globally each year, and human error is identified as the contributing factor in more than 90% of these incidents. Proponents of autonomous technology argue that replacing human judgment with machine precision could dramatically reduce this toll. However, critics point out that early-stage autonomous systems have produced their own category of errors — including failures to recognize unusual road markings, difficulty navigating in heavy rain or snow, and a documented inability to interpret the informal hand signals sometimes used by traffic officers. These limitations suggest that the transition from human-controlled to machine-controlled transport will be neither swift nor without complication.", "[1] Beyond safety, the widespread adoption of autonomous vehicles could reshape urban infrastructure in ways that planners are only beginning to anticipate. If self-driving cars become the norm, the need for large urban parking areas could decline significantly, since autonomous vehicles could drop passengers off and continue moving or return home rather than occupying a parking space for hours. [2] Traffic flow in cities might also improve substantially, as vehicle-to-vehicle communication systems could allow cars to travel in coordinated convoys at consistent speeds, eliminating the stop-and-start patterns that currently cause congestion. [3] Land currently devoted to parking lots and multi-story car parks could be repurposed for housing, green spaces, or community facilities. [4] Some urban planners envision a future in which privately owned cars are largely replaced by fleets of shared autonomous vehicles, fundamentally altering not only how cities are designed but also how people think about vehicle ownership itself.", "The ethical dimensions of autonomous vehicle decision-making have also attracted considerable academic and public debate. When an accident becomes unavoidable, how should a self-driving system be programmed to respond? Should it prioritize the safety of its passengers above all else, or should it calculate the option that minimizes total harm — even if that means placing the passenger at greater risk? These questions, often framed through the lens of classic philosophical thought experiments, do not have universally agreed-upon answers. Different countries and cultures may hold fundamentally different moral intuitions about how machines should be made to behave in life-or-death situations, complicating the prospect of developing a single global ethical standard.", "Legal and regulatory frameworks have struggled to keep pace with the speed of technological development. In most countries, existing traffic laws were written with a human driver in mind and do not straightforwardly accommodate vehicles that operate without one. Questions of liability in the event of an accident are particularly unresolved: if a self-driving car causes a collision, is the manufacturer, the software developer, the vehicle owner, or some combination of parties responsible? Several jurisdictions have begun drafting autonomous vehicle legislation, but the absence of internationally harmonized standards continues to create uncertainty for both developers and consumers.", "Despite these unresolved complexities, investment in autonomous vehicle technology continues to grow. Major technology firms, automotive manufacturers, and venture capital funds are collectively pouring billions of dollars into research and development each year. The timeline for full public deployment remains a subject of debate — some industry analysts predict widespread availability within the next decade, while others argue that truly reliable, fully autonomous systems may remain at least twenty years away. What seems certain, however, is that the journey toward self-driving transportation has already fundamentally altered the relationship between human beings, machines, and the roads they share."], questions: [{ q: "What is the main idea of the passage?", options: ["The development of autonomous vehicles involves significant technological progress alongside unresolved safety, ethical, and legal challenges.", "The primary goal of autonomous vehicle research is to reduce urban traffic congestion.", "Governments around the world have failed to create effective regulations for self-driving technology.", "Autonomous vehicles are already safer than human-driven cars and will soon replace them entirely."], answer: 0 }, { q: "According to the passage, what is the function of LiDAR in autonomous vehicle systems?", options: ["It communicates with traffic signals to adjust a vehicle's speed automatically.", "It uses laser technology to generate detailed three-dimensional maps of the surroundings.", "It connects the vehicle to satellite navigation systems for real-time route planning.", "It records video footage of the road for later review by engineers."], answer: 1 }, { q: "The word \"dramatically\" in paragraph 3 is closest in meaning to _______.", options: ["slowly but consistently", "in a significantly noticeable way", "in an unpredictable manner", "gradually and carefully"], answer: 1 }, { q: "According to the passage, what is the main argument used by supporters of autonomous vehicle technology regarding road safety?", options: ["Autonomous vehicles are cheaper to maintain than human-driven cars, reducing the overall cost of accidents.", "Since human error accounts for the vast majority of road accidents, replacing human judgment with machine systems could save many lives.", "Machine systems have already been proven to have zero failure rates in real-world conditions.", "Autonomous vehicles can communicate with emergency services faster than any human driver."], answer: 1 }, { q: "According to the passage, which of the following is NOT mentioned as a limitation of current autonomous vehicle systems?", options: ["Difficulty recognizing non-standard road markings.", "Reduced performance in poor weather conditions such as heavy rain.", "Inability to interpret hand signals from traffic officers.", "Failure to respond correctly to verbal commands from passengers."], answer: 3 }, { q: "According to the passage, how might the widespread adoption of autonomous vehicles affect urban land use?", options: ["It could free up land currently used for parking, which might then be converted into housing or green spaces.", "It would make public transportation systems unnecessary, allowing subway infrastructure to be removed.", "It would cause urban populations to migrate away from city centers toward suburban areas.", "It would require cities to build more multi-level parking structures to accommodate larger vehicle fleets."], answer: 0 }, { q: "The word \"harmonized\" in paragraph 6 is closest in meaning to _______.", options: ["made consistent and compatible across different systems or regions", "simplified to remove unnecessary complexity", "enforced strictly by international courts", "negotiated privately between technology companies"], answer: 0 }, { q: "The word \"These\" in paragraph 2 refers to _______.", options: ["the onboard computers that evaluate variables per second.", "the cameras, radar, and LiDAR sensors used by autonomous systems.", "the three-dimensional maps created of the surrounding environment.", "the obstacles and traffic signals detected on public roads."], answer: 1 }, { q: "Based on information from paragraphs 5 and 6, what can be inferred about the prospect of establishing a single global standard for autonomous vehicle regulation?", options: ["It has already been agreed upon in principle but is waiting for full technological deployment before implementation.", "It is unnecessary because individual countries already have sufficient legal frameworks in place.", "It faces significant obstacles due to differing ethical values across cultures and the absence of internationally aligned legal frameworks.", "It is likely to be achieved within the next five years as technology companies collaborate with governments."], answer: 2 }, { q: "Which of the following square brackets [1] , [2] , [3] , or [4] best indicates where the following sentence could be added to paragraph 4? \"This shift in land use could have cascading effects on local economies and neighborhood character.\"", options: ["[1]", "[2]", "[3]", "[4]"], answer: 2 }] },
    { title: "Climate Resilience: Adapting to a Changing Planet", paragraphs: ["The scientific consensus on anthropogenic climate change has, over the past three decades, shifted from a matter of active academic debate to one of near-universal agreement among researchers in relevant disciplines. What remains far more contested, however, is not the fact of climate change but the question of how human societies should respond to it. Two broad strategies have dominated policy discourse: mitigation, which seeks to reduce greenhouse gas emissions at their source, and adaptation, which accepts that a degree of climate disruption is already inevitable and focuses instead on building the capacity of communities and ecosystems to withstand its consequences. [1] Increasingly, climate scientists and policymakers argue that neither approach alone is sufficient and that a meaningful response to the climate crisis demands the simultaneous and coordinated pursuit of both. [2]", "The concept of climate resilience sits at the intersection of these two strategies, though its emphasis falls more heavily on the adaptive side. A resilient system — whether a city, an agricultural region, or a coastal ecosystem — is one that can absorb the shocks of climate-related disruption, reorganize in response to changed conditions, and continue to function without catastrophic loss of its essential structures and services. This definition, drawn from systems ecology and increasingly adopted in urban planning and development policy, implies that resilience is not simply the absence of vulnerability but an active, ongoing capacity that must be deliberately cultivated and maintained.", "One of the most extensively studied arenas of climate resilience is coastal infrastructure. As sea levels rise and the frequency of extreme weather events increases, low-lying coastal cities face compounding risks that traditional engineering approaches were never designed to address. In response, planners in cities such as Rotterdam, New York, and Jakarta have begun experimenting with what practitioners call \"green-grey infrastructure\" — hybrid systems that combine engineered structures such as flood barriers and elevated roadways with nature-based solutions including restored mangrove forests, constructed wetlands, and oyster reef rehabilitation. These hybrid approaches are considered superior to purely engineered solutions not only because they tend to be more cost-effective over the long term, but because they simultaneously deliver ecological co-benefits such as improved water quality, enhanced biodiversity, and carbon sequestration.", "Agricultural adaptation represents another critical dimension of climate resilience, and one whose urgency is particularly acute in regions of the developing world. Shifting precipitation patterns, prolonged droughts, and the increasing unpredictability of growing seasons are already undermining food security in parts of sub-Saharan Africa, South Asia, and Central America. Researchers have responded by developing drought-resistant and heat-tolerant crop varieties through both conventional breeding programs and, more controversially, genetic modification. Beyond crop development, adaptation strategies in agriculture also encompass the adoption of precision irrigation systems that dramatically reduce water consumption, the reintroduction of traditional farming techniques that have historically proved effective under variable conditions, and the construction of community-level grain storage facilities designed to buffer against seasonal shortfalls.", "The social dimensions of climate resilience have received comparatively less attention in mainstream policy discussions, yet they arguably underpin the effectiveness of all physical and technological interventions. Communities with strong social cohesion, functioning institutions, diverse economic bases, and equitable access to resources consistently demonstrate greater capacity to recover from climate shocks than those characterized by inequality, institutional fragility, or economic monoculture. This pattern holds across geographies and income levels: a wealthy coastal city with degraded social infrastructure may prove less resilient in practice than a modestly resourced community with robust local governance and deep reserves of collective knowledge about managing environmental risk.", "Critics of mainstream climate resilience discourse have raised a more fundamental concern: that the framing of resilience as an adaptive capacity implicitly normalizes a level of climate disruption that ought instead to be prevented. By focusing on the ability to \"bounce back\" from climate impacts, these critics argue, resilience frameworks may inadvertently reduce pressure on governments and corporations to pursue the deep structural changes — in energy systems, land use, and industrial production — that genuine mitigation requires. This tension between adaptation and mitigation is not merely theoretical; it has concrete implications for how limited financial and political resources are allocated at both national and international levels.", "Reconciling these competing priorities remains one of the most intellectually and politically demanding challenges of the current era. The most productive framing may be one that treats resilience not as an alternative to systemic transformation but as a necessary complement to it — a way of protecting communities during the decades-long transition to a lower-carbon economy while simultaneously working to ensure that the worst projected climate outcomes are avoided altogether. Whether political systems characterized by short electoral cycles and competing institutional interests can sustain the long-term, cross-sectoral coordination that such an approach demands is, perhaps, the most consequential open question of all."], questions: [{ q: "Which of the following best captures the central argument of the passage?", options: ["Nature-based solutions are universally superior to engineered approaches when addressing climate-related risks.", "Climate resilience is a multidimensional concept that involves physical, agricultural, and social strategies, yet remains subject to fundamental conceptual tensions.", "The primary obstacle to effective climate policy is the failure of governments to invest adequately in coastal infrastructure.", "Mitigation strategies have proven far more effective than adaptation in addressing the consequences of climate change."], answer: 1 }, { q: "The word \"underpin\" in paragraph 5 is closest in meaning to _______.", options: ["complicate and destabilize", "replace and supersede", "formally evaluate and measure", "provide the foundational support for"], answer: 3 }, { q: "According to the passage, why do planners consider \"green-grey infrastructure\" preferable to purely engineered solutions?", options: ["Because engineered solutions require more frequent replacement and generate higher long-term maintenance costs than any nature-based alternative.", "Because nature-based solutions have been proven to completely eliminate the risk of flooding in low-lying coastal areas.", "Because international funding agencies exclusively support hybrid infrastructure projects over conventional flood barriers.", "Because hybrid systems are both more cost-effective over time and deliver additional ecological benefits such as improved biodiversity and carbon sequestration."], answer: 3 }, { q: "According to the passage, which of the following is described as a strategy for agricultural adaptation to climate change?", options: ["Replacing all traditional farming techniques with modern mechanized systems to increase output.", "Relocating farming communities from drought-prone regions to areas with more stable rainfall.", "Adopting precision irrigation systems that significantly reduce the amount of water used in agriculture.", "Establishing international commodity markets to stabilize food prices during climate-related disruptions."], answer: 2 }, { q: "According to the passage, what does the author suggest about the relationship between social factors and climate resilience?", options: ["Wealthier communities are always better equipped to recover from climate disruptions regardless of their social infrastructure.", "Social cohesion and equitable resource access are more important determinants of resilience than physical or technological measures alone.", "Communities in the developing world consistently demonstrate greater resilience than those in wealthy nations.", "Social resilience can only be built through large-scale government intervention and centralized planning."], answer: 1 }, { q: "The word \"inadvertently\" in paragraph 6 is closest in meaning to _______.", options: ["in a way that produces immediate and measurable results", "in a manner that is openly acknowledged", "deliberately and strategically", "without intending to, as an unintended side effect"], answer: 3 }, { q: "The word \"its\" in paragraph 2 refers to _______.", options: ["the concept of climate resilience.", "the definition drawn from systems ecology.", "the mitigation strategy outlined in paragraph 1.", "the adaptive capacity of coastal ecosystems."], answer: 0 }, { q: "According to the passage, which of the following is NOT mentioned as a benefit of green-grey infrastructure systems?", options: ["Elimination of the need for governmental flood insurance programs.", "Enhanced biodiversity in coastal areas.", "Carbon sequestration through restored natural features.", "Improved water quality in surrounding environments."], answer: 0 }, { q: "Based on paragraph 6, what can be inferred about critics who argue that resilience frameworks may reduce pressure for systemic change?", options: ["They believe adaptation strategies should be abandoned entirely in favor of mitigation efforts.", "They maintain that resilience is only relevant for developing nations and not for industrialized economies.", "They argue that resilience frameworks are scientifically unsound and lack empirical support.", "They are concerned that emphasizing adaptive capacity may implicitly lower ambitions for the deep structural reforms that emissions reduction requires."], answer: 3 }, { q: "Which of the following square brackets [1] , [2] , [3] , or [4] best indicates where the following sentence could be added to paragraph 1? \"This dual imperative has prompted a growing body of integrated policy frameworks that refuse to treat the two goals as mutually exclusive.\"", options: ["[1]", "[2]", "[3]", "[4]"], answer: 1 }] },
  ] },
];
